const BEATS={"a1s1":[[2,"Richard calls Bolingbroke and Mowbray before him"],[11,"Bolingbroke accuses Mowbray of treason"],[13,"Gloves are thrown down"],[16,"The charge: Mowbray murdered Gloucester"],[21,"Richard and Gaunt cannot make peace between them"],[32,"Richard orders a trial by combat at Coventry"]],"a1s2":[[36,"The Duchess of Gloucester begs Gaunt for revenge"],[38,"Gaunt: only God may punish the king's deputy"],[41,"She hopes Bolingbroke will kill Mowbray"],[43,"Her long farewell"]],"a1s3":[[52,"The champions are called to the lists"],[61,"Bolingbroke says goodbye to his king and his father"],[68,"Mowbray swears he is loyal"],[79,"Richard stops the fight at the last moment"],[81,"Bolingbroke is banished for ten years, Mowbray for life"],[92,"Mowbray warns that Richard will learn the truth"],[94,"Seeing Gaunt's grief, Richard cuts the sentence to six years"],[114,"Gaunt tries to comfort his son"],[118,"Bolingbroke's farewell to England"]],"a1s4":[[125,"Aumerle describes parting with Bolingbroke"],[128,"Richard mocks Bolingbroke's way with the common people"],[130,"He will lease out the kingdom to pay for the Irish war"],[136,"Gaunt is dying, and Richard hopes it is soon"]],"a2s1":[[141,"The dying Gaunt wants to warn Richard"],[145,"\"This scepter'd isle\": Gaunt's England, now leased out"],[150,"Richard arrives and Gaunt rebukes him"],[159,"Richard rages at the old man"],[170,"Gaunt is dead, and Richard seizes his wealth"],[171,"York protests and leaves"],[177,"Richard sails for Ireland, leaving York in charge"],[187,"The lords complain of Richard's wrongs"],[200,"Bolingbroke is on his way back with an army"]],"a2s2":[[206,"The Queen feels a grief she cannot name"],[215,"Green: Bolingbroke has landed"],[226,"York arrives, overwhelmed"],[229,"The Duchess of Gloucester is dead"],[235,"York is torn between king and nephew"],[237,"Bushy, Bagot and Green split up to save themselves"]],"a2s3":[[253,"Northumberland flatters Bolingbroke on the march"],[265,"Young Harry Percy offers his service"],[271,"More lords join Bolingbroke"],[278,"He insists he is now Lancaster"],[285,"York calls his nephew a traitor"],[288,"Bolingbroke: he has come only for his inheritance"],[294,"York cannot resist and stays neutral"],[295,"Bolingbroke vows to root out the king's favourites"]],"a2s4":[[300,"The Welsh captain will not wait any longer"],[302,"Omens say the king is dead"],[304,"Salisbury sees Richard's glory falling"]],"a3s1":[[308,"Bolingbroke condemns Bushy and Green"],[313,"Kind greetings to the Queen, then on to Glendower"]],"a3s2":[[321,"Richard lands in Wales and greets the earth"],[324,"God's angels will fight for the anointed king"],[327,"The Welsh army has gone"],[331,"Richard rallies himself: \"Am I not king?\""],[335,"Scroop brings news of executions"],[343,"\"Sad stories of the death of kings\""],[346,"Carlisle stirs him to fight back"],[348,"York has joined Bolingbroke; Richard gives up"]],"a3s3":[[354,"Bolingbroke's army reaches Flint Castle"],[368,"His terms: lift his banishment, return his lands"],[370,"Richard appears on the walls"],[372,"He warns of the bloodshed to come"],[376,"He gives in to everything"],[380,"Richard imagines trading his kingdom for a grave"],[382,"\"Down, down I come\""],[388,"Bolingbroke kneels; Richard agrees to go to London"]],"a3s4":[[406,"The Queen cannot be distracted"],[413,"Gardeners arrive and the Queen hides"],[415,"The garden as a badly kept kingdom"],[417,"Bolingbroke has captured the king"],[422,"The Queen bursts out at the gardener"],[426,"He plants rue where her tear fell"]],"a4s1":[[430,"Bagot accuses Aumerle of Gloucester's murder"],[437,"Lords throw down their gloves"],[453,"Mowbray has died in exile"],[458,"York: Richard will give up the crown"],[460,"Carlisle prophesies civil war and is arrested"],[467,"Richard is brought in"],[469,"He hands over the crown"],[477,"He refuses to read his crimes"],[490,"Richard calls for a mirror and smashes it"],[511,"A plot against the new king begins"]],"a5s1":[[515,"The Queen waits for Richard on his way to the Tower"],[519,"She is shocked at how meekly he accepts his fall"],[522,"He is sent to Pomfret, she to France"],[523,"Richard warns Northumberland of future treachery"],[525,"Their last farewell"]],"a5s2":[[545,"York describes Bolingbroke's welcome in London"],[547,"Dust thrown on Richard's head"],[557,"York spots a sealed paper on Aumerle"],[567,"A plot to kill the new king"],[573,"York calls for his boots to ride to the king"],[587,"The Duchess begs for her son and sends him ahead"]],"a5s3":[[598,"The new king worries about his wild son"],[604,"Aumerle rushes in and begs a pardon"],[615,"York hammers on the door"],[637,"The Duchess arrives and the family kneels"],[645,"She begs him to say \"pardon\""],[655,"Aumerle is pardoned; the other plotters will die"]],"a5s4":[[664,"Exton reads the king's wish and goes to kill Richard"]],"a5s5":[[668,"Alone in prison, Richard peoples his cell with thoughts"],[671,"A groom from his stable visits"],[675,"Bolingbroke rode Richard's horse at the coronation"],[681,"The keeper will not taste the food"],[684,"Richard beats the keeper; Exton's men burst in"],[692,"Struck down, Richard says his soul will rise"],[694,"Exton regrets it at once"]],"a5s6":[[698,"News that the rebels are crushed"],[707,"The chief conspirator is dead; Carlisle is spared"],[710,"Exton brings Richard's coffin"],[713,"Henry refuses to thank him and vows a crusade"]]};
